function __countLayersRecursive(layers) {
  var total = 0;
  var n = 0;
  try { n = layers.length; } catch (eN) { n = 0; }
  for (var i = 0; i < n; i++) {
    var candidate = null;
    try { candidate = layers[i]; } catch (eC) { continue; }
    if (!candidate) continue;
    total++;
    var isGroup = false;
    try { isGroup = (candidate instanceof LayerSet); } catch (eG) {}
    if (isGroup) {
